const items = $input.all().map(item => item.json);

const borderline = items.filter(i => i.audit_type === 'borderline');
const random = items.filter(i => i.audit_type === 'random');

function getSkipReason(item) {
  const blockers = item.semantic_blockers ?? {};

  const blocked = Object.entries(blockers)
    .filter(([_, value]) =>
      value?.blocked === true &&
      value?.confidence === 'high'
    )
    .map(([key, value]) => {
      const label = key.replace(/_/g, ' ');
      return `${label}: ${value.reason}`;
    });

  if (blocked.length > 0) {
    return blocked.join(' | ');
  }

  return item.scope_reason || item.summary || '—';
}

// Show borderline SKIPs first
const sorted = [...borderline, ...random];

function truncate(text, max = 260) {
  if (!text) return '—';
  const clean = String(text).replace(/\s+/g, ' ').trim();
  return clean.length > max
    ? clean.slice(0, max - 3) + '...'
    : clean;
}

let message = `🔎 WEEKLY SKIP AUDIT\n\n`;

if (borderline.length === 0) {
  message += `✅ No borderline SKIPs detected this week.\n`;
  message += `Random quality-control sample: ${random.length}\n\n`;
} else {
  message += `⚠️ Borderline SKIPs detected: ${borderline.length}\n`;
  message += `Random control sample: ${random.length}\n\n`;
}

sorted.forEach((item, index) => {
  const icon = item.audit_type === 'borderline' ? '⚠️' : '🎲';
  const type =
    item.audit_type === 'borderline'
      ? 'BORDERLINE SKIP'
      : 'RANDOM SKIP';

  message += `${icon} ${index + 1}. ${type}\n`;
  message += `${truncate(item.title, 120)}\n`;

  const scopeLabel = String(item.scope_status ?? '—')
  .replace(/_/g, ' ')
  .toUpperCase();

  message += `Score: ${item.total_score ?? '—'} | Scope: ${scopeLabel}\n`;

  message += `Why SKIP: ${truncate(getSkipReason(item))}\n`;
  message += `${item.url ?? ''}\n\n`;
});

// Protect against Telegram message length limits
if (message.length > 3900) {
  message = message.slice(0, 3850) +
    '\n\n⚠️ Digest truncated due to Telegram message limit.';
}

return [
  {
    json: {
      text: message,
      audited_count: items.length,
      borderline_count: borderline.length,
      random_count: random.length
    }
  }
];
